function extractDate(text){const m=text.match(/\b(20\d{2})[-/](\d{1,2})[-/](\d{1,2})\b/);if(m){let d=`${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;if(!Number.isNaN(dateObj(d).getTime()))return d;}const named=text.match(/\b(?:due|deadline|submit(?: by)?|before|on)\s*[:\-]?\s*(?:\w+day,?\s*)?(\d{1,2})(?:st|nd|rd|th)?\s+(January|February|March|April|May|June|July|August|September|October|November|December)(?:\s*,?\s*(20\d{2}))?/i)||text.match(/\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s*(20\d{2}))?/i);if(named){let day,month,year;if(/^\d/.test(named[1])){day=named[1];month=named[2];year=named[3]}else{month=named[1];day=named[2];year=named[3]}let d=new Date(`${month} ${day}, ${year||today.getFullYear()}`);if(!Number.isNaN(d.getTime()))return iso(d)}return ''}
function extractTime(text){let m=text.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);if(!m)return '23:59';let h=Number(m[1])%12+(m[3].toLowerCase()==='pm'?12:0);return `${String(h).padStart(2,'0')}:${m[2]||'00'}`}
