async function recognizeCanvas(canvas){const {createWorker}=await import('tesseract.js');const worker=await createWorker('eng');try{const result=await worker.recognize(canvas);return result.data.text||''}finally{await worker.terminate()}}
async function fileText(file){if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){let pdf=await pdfjsLib.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let texts=[];for(let i=1;i<=Math.min(pdf.numPages,30);i++){let p=await pdf.getPage(i);let t=await p.getTextContent();let raw=t.items.map(x=>x.str).join(' ').trim();if(raw.length<35){let viewport=p.getViewport({scale:2});let canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await p.render({canvasContext:canvas.getContext('2d'),viewport}).promise;raw=await recognizeCanvas(canvas)}texts.push(raw)}return texts.join('\n')}if(file.type.startsWith('image/')||/\.(png|jpe?g|webp)$/i.test(file.name)){let image=await createImageBitmap(file);let canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0);image.close();return recognizeCanvas(canvas)}return await file.text()}
const clock=(str)=>{let m=String(str).match(/(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?/i);if(!m)return null;let h=+m[1],min=+(m[2]||0);if(m[3])h=h%12+(m[3].toLowerCase()==='pm'?12:0);if(h>23||min>59)return null;return String(h).padStart(2,'0')+':'+String(min).padStart(2,'0')};
const timePairs=(line)=>{let re=/(\d{1,2}(?:[:.]\d{2})?\s*(?:am|pm)?)\s*(?:-|–|—|to)\s*(\d{1,2}(?:[:.]\d{2})?\s*(?:am|pm)?)/gi;return [...line.matchAll(re)].map(m=>[clock(m[1]),clock(m[2])]).filter(t=>t[0]&&t[1]&&t[0]<t[1])};
function recognizeTimetable(text,subjects){const result=[];const seen=new Set();const aliases=s=>[s.name,s.short,s.id].filter(Boolean);const subjectFor=line=>subjects.find(s=>aliases(s).some(a=>new RegExp('(^|[^a-z0-9])'+a.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^a-z0-9])','i').test(line)))||null;
const push=(day,subject,start,end,room='')=>{if(day<0||!subject||!start||!end||start>=end)return;let key=[day,subject.id,start,end].join('|');if(!seen.has(key)){seen.add(key);result.push({id:Date.now()+result.length,day,subject:subject.id,start,end,room})}};
let lines=text.split(/\n/).map(x=>x.trim()).filter(Boolean);
// Conventional day-first rows and OCR output containing explicit weekday labels.
for(let line of lines){let day=weekdays.findIndex(w=>new RegExp('\\b'+w+'\\b','i').test(line));if(day<0)day=weekdays.findIndex(w=>new RegExp('(^|\\W)'+w.slice(0,3)+'(?=\\W|$)','i').test(line));if(day<0)continue;let subject=subjectFor(line);for(let [start,end] of timePairs(line))push(day,subject,start,end);let times=[...line.matchAll(/\b([01]?\d|2[0-3])[:.]([0-5]\d)\b/g)].map(m=>clock(m[0]));if(subject&&times.length>=2)push(day,subject,times[0],times[1])}
// Timetable matrix: weekday columns, times in the left column, subjects in cells.
let headerIndex=lines.findIndex(line=>weekdays.filter(w=>new RegExp('\\b'+w.slice(0,3),'i').test(line)).length>=3);
if(headerIndex>=0){let header=lines[headerIndex];let columns=[...header.matchAll(/Mon(?:day)?|Tue(?:sday)?|Wed(?:nesday)?|Thu(?:rsday)?|Fri(?:day)?|Sat(?:urday)?|Sun(?:day)?/gi)].map(m=>weekdays.findIndex(w=>w.toLowerCase().startsWith(m[0].slice(0,3).toLowerCase())));for(let line of lines.slice(headerIndex+1)){let pair=timePairs(line)[0];if(!pair)continue;let cells=line.split(/\s{2,}|\t|\|/).map(x=>x.trim()).filter(Boolean);if(cells.length>=columns.length+1){columns.forEach((day,i)=>push(day,subjectFor(cells[i+1]),pair[0],pair[1]))}}}
return result.sort((a,b)=>a.day-b.day||a.start.localeCompare(b.start))}
