const daysInMonth=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();const offset=(new Date(month.getFullYear(),month.getMonth(),1).getDay()+6)%7;const cells=[...Array(offset).fill(null),...Array.from({length:daysInMonth},(_,i)=>i+1)];const byDate=(d)=>data.filter(t=>t.due===d);const isOverdue=(t)=>t.status!=='done'&&`${t.due}T${t.time||'23:59'}`<new Date().toLocaleString('sv-SE').replace(' ','T').slice(0,16);const daySummary=(d)=>{const items=byDate(d);return {total:items.length,done:items.filter(t=>t.status==='done').length,progress:items.filter(t=>t.status==='progress').length,overdue:items.filter(isOverdue).length,open:items.filter(t=>t.status!=='done'&&!isOverdue(t)).length}};const ttKey=who==='friend'?'friend':'student';const slots=timetable[ttKey]||[];const saveSlot=()=>{if(!ttDraft.subject)return;setTimetable(old=>({...old,[ttKey]:[...(old[ttKey]||[]),{...ttDraft,day:ttDay,id:Date.now()}].sort((a,b)=>a.day-b.day||a.start.localeCompare(b.start))}));setToast({id:Date.now(),title:'Class added to timetable',detail:'Daily timetable updated.'})};const importTimetable=async(file)=>{if(!file)return;setTtBusy(true);setTtPreview([]);setTtNote('Extracting timetable (OCR may take a minute)…');try{let content=await fileText(file);let found=recognizeTimetable(content,p.subjects);setTtPreview(found);setTtNote(found.length?`Detected ${found.length} class(es). Review the preview and click Import confirmed classes. OCR can misread times and subjects.`:'No classes confidently detected. Try a clearer scan or manually add classes. For grid layouts, exported text PDFs usually work best.')}catch(e){setTtNote('Could not process file: '+e.message)}finally{setTtBusy(false)}};const weekdayForDate=(d)=>(dateObj(d).getDay()+6)%7;
const selectedDaySlots=slots.filter(x=>x.day===weekdayForDate(selectedDay)).sort((a,b)=>a.start.localeCompare(b.start));
